'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-gfirst-index-greater-than';


// MAIN //

/**
* Returns the index of the first element in a one-dimensional ndarray which is greater than a corresponding element in another one-dimensional ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*
* -   When comparing elements, the function checks whether an element in the first one-dimensional input ndarray is greater than a corresponding element in the second one-dimensional input ndarray using the greater-than operator `>`. As a consequence, comparisons involving `NaN` always evaluate to `false`.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* import vector from '@stdlib/ndarray-vector-ctor';
*
* var x = vector( [ 0.0, 0.0, 1.0, 0.0 ], 'generic' );
* var y = vector( [ 0.0, 0.0, 0.0, 0.0 ], 'generic' );
*
* var idx = gfirstIndexGreaterThan( [ x, y ] );
* // returns 2
*/
function gfirstIndexGreaterThan( arrays ) {
	var x = arrays[ 0 ];
	var y = arrays[ 1 ];
	return strided( numelDimension( x, 0 ), getData( x ), getStride( x, 0 ), getOffset( x ), getData( y ), getStride( y, 0 ), getOffset( y ) ); // eslint-disable-line max-len
}


// EXPORTS //

export default gfirstIndexGreaterThan;
